CREATE POLICY "Users view own supabase op logs" ON public.supabase_operation_logs FOR SELECT USING (((auth.uid() = user_id) OR public.has_role(auth.uid(), 'admin'::public.app_role)));
CREATE POLICY "Users view own tickets" ON public.support_tickets FOR SELECT USING (((auth.uid() = user_id) OR public.has_role(auth.uid(), 'admin'::public.app_role)));
CREATE POLICY "Users view own transactions" ON public.credit_transactions FOR SELECT USING (((auth.uid() = user_id) OR public.has_role(auth.uid(), 'admin'::public.app_role)));
CREATE POLICY "Users view ticket messages" ON public.support_messages FOR SELECT USING ((public.has_role(auth.uid(), 'admin'::public.app_role) OR (EXISTS ( SELECT 1 FROM public.support_tickets t WHERE ((t.id = support_messages.ticket_id) AND (t.user_id = auth.uid()))))));
CREATE POLICY "users delete own project memory" ON public.project_memory FOR DELETE USING ((auth.uid() = user_id));
CREATE POLICY "users insert own project memory" ON public.project_memory FOR INSERT WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "users update own project memory" ON public.project_memory FOR UPDATE USING ((auth.uid() = user_id));
CREATE POLICY "users view own project memory" ON public.project_memory FOR SELECT USING ((auth.uid() = user_id));